package service;
import db.*;import java.sql.*;import java.time.*;import java.util.*;import util.KetNoiDB;
/** S6-06: phân tuyến theo khu vực, lưu thứ tự và liên hệ tại lúc lập chuyến. */
public class ChuyenGiaoService {
 public Map<String,Object> list(long user,Collection<String> roles)throws SQLException{try(Connection c=KetNoiDB.getConnection()){String scope=KhoService.manager(roles)?"":" AND EXISTS(SELECT 1 FROM user_warehouses uw WHERE uw.user_id=? AND uw.warehouse_id=t.warehouse_id)";return Map.of("items",TruyVanDB.rows(c,"SELECT t.id,t.code,t.region,t.status,t.expected_at::text expected_at,t.departed_at::text departed_at,w.name warehouse,d.name driver,v.plate vehicle,(SELECT count(*) FROM delivery_trip_stops s WHERE s.trip_id=t.id) stops FROM delivery_trips t JOIN warehouses w ON w.id=t.warehouse_id JOIN delivery_drivers d ON d.id=t.driver_id JOIN delivery_vehicles v ON v.id=t.vehicle_id WHERE true"+scope+" ORDER BY t.id DESC LIMIT 200",KhoService.manager(roles)?new Object[]{}:new Object[]{user}),"drivers",TruyVanDB.rows(c,"SELECT id,name,phone FROM delivery_drivers WHERE active ORDER BY name"),"vehicles",TruyVanDB.rows(c,"SELECT id,plate FROM delivery_vehicles WHERE active ORDER BY plate"),"canManage",KhoService.manager(roles));}}
 public List<Map<String,Object>> orders(long user,Collection<String> roles)throws SQLException{try(Connection c=KetNoiDB.getConnection()){String scope=KhoService.manager(roles)?"":" AND EXISTS(SELECT 1 FROM user_warehouses uw WHERE uw.user_id=? AND uw.warehouse_id=o.warehouse_id)";return TruyVanDB.rows(c,"SELECT o.id,o.code,o.warehouse_id,k.region,k.name customer,o.delivery_address FROM orders o JOIN customers k ON k.id=o.agent_id WHERE o.status='SHIPPED' AND NOT EXISTS(SELECT 1 FROM delivery_trip_stops s WHERE s.order_id=o.id) AND NOT EXISTS(SELECT 1 FROM delivery_confirmations dc WHERE dc.order_id=o.id)"+scope+" ORDER BY k.region,o.id DESC LIMIT 500",KhoService.manager(roles)?new Object[]{}:new Object[]{user});}}
 public Map<String,Object> detail(long id,long user,Collection<String> roles)throws SQLException{try(Connection c=KetNoiDB.getConnection()){var h=TruyVanDB.one(c,"SELECT t.id,t.code,t.warehouse_id,t.region,t.status,t.expected_at::text expected_at,t.departed_at::text departed_at,w.name warehouse,d.name driver,d.phone driver_phone,v.plate vehicle FROM delivery_trips t JOIN warehouses w ON w.id=t.warehouse_id JOIN delivery_drivers d ON d.id=t.driver_id JOIN delivery_vehicles v ON v.id=t.vehicle_id WHERE t.id=?",id);if(h==null)throw new NoSuchElementException("Không tìm thấy chuyến giao");KhoService.access(c,((Number)h.get("warehouse_id")).longValue(),user,roles);h.put("stops",TruyVanDB.rows(c,"SELECT s.id,s.order_id,s.sequence,s.address,s.recipient_name,s.phone,o.code order_code,o.status order_status,dc.outcome,dc.returned_to_warehouse FROM delivery_trip_stops s JOIN orders o ON o.id=s.order_id LEFT JOIN delivery_confirmations dc ON dc.order_id=o.id WHERE s.trip_id=? ORDER BY s.sequence",id));return h;}}
 public long resource(long user,Collection<String> roles,Map<String,Object> in)throws SQLException{if(!KhoService.manager(roles))throw new SecurityException("Chỉ quản lý kho được khai báo tài xế và phương tiện");String type=KhoService.text(in.get("type"),"Loại",20,true);try(Connection c=KetNoiDB.getConnection()){c.setAutoCommit(false);try{KhoService.actor(c,user);long id;if(type.equals("driver")){String name=KhoService.text(in.get("name"),"Tên tài xế",150,true),phone=KhoService.text(in.get("phone"),"Điện thoại",20,true);id=TruyVanDB.id(TruyVanDB.one(c,"INSERT INTO delivery_drivers(name,phone) VALUES(?,?) RETURNING id",name,phone));}else if(type.equals("vehicle")){String plate=KhoService.text(in.get("plate"),"Biển số",30,true).toUpperCase(Locale.ROOT);id=TruyVanDB.id(TruyVanDB.one(c,"INSERT INTO delivery_vehicles(plate) VALUES(?) RETURNING id",plate));}else throw new IllegalArgumentException("Loại tài nguyên không hợp lệ");c.commit();return id;}catch(SQLException|RuntimeException e){c.rollback();throw e;}}}
 public long create(long user,Collection<String> roles,Map<String,Object> in)throws SQLException{
  long driver=KhoService.id(in.get("driverId")),vehicle=KhoService.id(in.get("vehicleId"));LocalDateTime expected;try{expected=LocalDateTime.parse(KhoService.text(in.get("expectedAt"),"Giờ dự kiến",30,true));}catch(Exception e){throw new IllegalArgumentException("Giờ dự kiến không hợp lệ");}if(!expected.isAfter(LocalDateTime.now())||expected.isAfter(LocalDateTime.now().plusDays(90)))throw new IllegalArgumentException("Giờ kết thúc dự kiến phải trong 90 ngày tới");
  if(!(in.get("orderIds") instanceof List<?> raw)||raw.isEmpty()||raw.size()>200)throw new IllegalArgumentException("Chọn từ 1 đến 200 đơn");var ids=new ArrayList<Long>();for(Object x:raw){long id=KhoService.id(x);if(ids.contains(id))throw new IllegalArgumentException("Đơn bị trùng");ids.add(id);}
  try(Connection c=KetNoiDB.getConnection()){c.setAutoCommit(false);try{KhoService.actor(c,user);if(TruyVanDB.one(c,"SELECT id FROM delivery_drivers WHERE id=? AND active FOR UPDATE",driver)==null||TruyVanDB.one(c,"SELECT id FROM delivery_vehicles WHERE id=? AND active FOR UPDATE",vehicle)==null)throw new IllegalArgumentException("Tài xế hoặc xe không còn hoạt động");
   Map<Long,Map<String,Object>> orders=new HashMap<>();Long wh=null;String region=null;
   for(long id:new TreeSet<>(ids)){var o=TruyVanDB.one(c,"SELECT o.id,o.status,o.warehouse_id,o.delivery_address,k.region,COALESCE(a.recipient_name,k.name) recipient_name,COALESCE(a.phone,k.phone) phone FROM orders o JOIN customers k ON k.id=o.agent_id LEFT JOIN customer_addresses a ON a.id=o.delivery_address_id WHERE o.id=? FOR UPDATE OF o",id);if(o==null||!"SHIPPED".equals(o.get("status"))||TruyVanDB.one(c,"SELECT 1 FROM delivery_trip_stops WHERE order_id=?",id)!=null||TruyVanDB.one(c,"SELECT 1 FROM delivery_confirmations WHERE order_id=?",id)!=null)throw new IllegalArgumentException("Đơn chưa xuất kho, đã có kết quả giao hoặc đã được phân chuyến");long warehouse=((Number)o.get("warehouse_id")).longValue();KhoService.access(c,warehouse,user,roles);if(wh!=null&&(wh!=warehouse||!region.equals(o.get("region"))))throw new IllegalArgumentException("Các đơn phải cùng kho và cùng khu vực");wh=warehouse;region=String.valueOf(o.get("region"));KhoService.text(o.get("delivery_address"),"Địa chỉ giao",1000,true);KhoService.text(o.get("phone"),"Điện thoại người nhận",20,true);orders.put(id,o);}
   long trip=TruyVanDB.id(TruyVanDB.one(c,"INSERT INTO delivery_trips(code,warehouse_id,region,driver_id,vehicle_id,expected_at,created_by) VALUES(?,?,?,?,?,?,?) RETURNING id","CG-"+UUID.randomUUID().toString().substring(0,12).toUpperCase(Locale.ROOT),wh,region,driver,vehicle,Timestamp.valueOf(expected),user));int seq=0;for(long id:ids){var o=orders.get(id);TruyVanDB.update(c,"INSERT INTO delivery_trip_stops(trip_id,order_id,sequence,address,recipient_name,phone) VALUES(?,?,?,?,?,?)",trip,id,++seq,o.get("delivery_address"),o.get("recipient_name"),o.get("phone"));}c.commit();return trip;
  }catch(SQLException|RuntimeException e){c.rollback();throw e;}}
 }
 public void start(long id,long user,Collection<String> roles)throws SQLException{try(Connection c=KetNoiDB.getConnection()){c.setAutoCommit(false);try{var t=TruyVanDB.one(c,"SELECT * FROM delivery_trips WHERE id=? FOR UPDATE",id);if(t==null)throw new NoSuchElementException("Không tìm thấy chuyến");KhoService.access(c,((Number)t.get("warehouse_id")).longValue(),user,roles);if(!"DRAFT".equals(t.get("status")))throw new IllegalArgumentException("Chỉ khởi hành chuyến nháp");if(!((Timestamp)t.get("expected_at")).toLocalDateTime().isAfter(LocalDateTime.now()))throw new IllegalArgumentException("Chuyến đã quá giờ dự kiến");if(TruyVanDB.one(c,"SELECT id FROM delivery_drivers WHERE id=? AND active FOR UPDATE",t.get("driver_id"))==null||TruyVanDB.one(c,"SELECT id FROM delivery_vehicles WHERE id=? AND active FOR UPDATE",t.get("vehicle_id"))==null)throw new IllegalArgumentException("Tài xế hoặc xe đã ngừng hoạt động");if(TruyVanDB.one(c,"SELECT 1 FROM delivery_trips WHERE status='IN_TRANSIT' AND (driver_id=? OR vehicle_id=?) LIMIT 1",t.get("driver_id"),t.get("vehicle_id"))!=null)throw new IllegalArgumentException("Tài xế hoặc xe đang thực hiện chuyến khác");if(TruyVanDB.one(c,"SELECT 1 FROM delivery_trip_stops s JOIN orders o ON o.id=s.order_id LEFT JOIN delivery_confirmations dc ON dc.order_id=o.id WHERE s.trip_id=? AND (o.status<>'SHIPPED' OR dc.id IS NOT NULL) LIMIT 1",id)!=null)throw new IllegalArgumentException("Đơn trong chuyến đã đổi trạng thái giao hàng");KhoService.actor(c,user);TruyVanDB.update(c,"UPDATE delivery_trips SET status='IN_TRANSIT',departed_at=CURRENT_TIMESTAMP WHERE id=?",id);c.commit();}catch(SQLException|RuntimeException e){c.rollback();throw e;}}}
}
